import type { BaseVariableConfig } from '../../Variable'

/**
 * Configuration type for rich text label variable
 * @interface
 */
export type RichTextLabelVariableType<Type extends string = string> = Omit<BaseVariableConfig<Type>, 'question'> & {
    /** Indicates this is a rich text variable type */
    richText: string
}

/**
 * A CatalogItem variable for a rich text label field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the rich text label variable including:
 *   * **richText** - Indicates this is a rich text variable type
 *   * And all other properties from the base Variable type
 * @group ServiceCatalog/Variables
 */
export function RichTextLabelVariable(config: RichTextLabelVariableType) {
    return config
}
